spark.sql(r"""
WITH fills AS (
  SELECT
    d.patient_id,
    d.product_id,
    d.dispense_date,
    DATEADD(DAY, d.days_supply, d.dispense_date) AS supply_end_date,
    ROW_NUMBER() OVER (PARTITION BY d.patient_id, d.product_id ORDER BY d.dispense_date, d.dispense_id) AS fill_seq,
    LEAD(d.dispense_date) OVER (PARTITION BY d.patient_id, d.product_id ORDER BY d.dispense_date, d.dispense_id) AS next_dispense_date
  FROM dbo.dispenses AS d
  WHERE
    d.status = 'DISPENSED' AND d.dispense_date <= CAST(:as_of_date AS DATE)
), gaps AS (
  SELECT
    patient_id,
    product_id,
    fill_seq,
    dispense_date,
    supply_end_date,
    next_dispense_date,
    DATEDIFF(
      DAY,
      CAST(supply_end_date AS TIMESTAMP),
      CAST(COALESCE(next_dispense_date, CAST(:as_of_date AS DATE)) AS TIMESTAMP)
    ) AS gap_days
  FROM fills
)
INSERT INTO dbo.refill_gap_events (
  patient_id,
  product_id,
  fill_seq,
  dispense_date,
  supply_end_date,
  next_dispense_date,
  gap_days,
  gap_category,
  is_open_gap,
  calculated_at
)
SELECT
  patient_id,
  product_id,
  fill_seq,
  dispense_date,
  supply_end_date,
  next_dispense_date,
  gap_days,
  CASE
    WHEN gap_days <= 0
    THEN 'ON_TIME'
    WHEN gap_days <= CAST(:gap_threshold_days AS INT)
    THEN 'MINOR_GAP'
    WHEN gap_days <= 30
    THEN 'MAJOR_GAP'
    ELSE 'LAPSED'
  END,
  CAST(CASE WHEN next_dispense_date IS NULL THEN 1 ELSE 0 END AS BOOLEAN),
  CURRENT_TIMESTAMP()
FROM gaps
WHERE
  gap_days > 0 OR next_dispense_date IS NULL
""", args={"as_of_date": as_of_date, "gap_threshold_days": gap_threshold_days})

